const input = require("fs").readFileSync(0, "utf8");

function minMeetingRooms(intervals) {
  const starts = intervals.map(([start]) => start).sort((a, b) => a - b);
  const ends = intervals.map(([, end]) => end).sort((a, b) => a - b);
  let inUse = 0;
  let most = 0;
  let i = 0;
  let j = 0;
  while (i < starts.length) {
    if (starts[i] < ends[j]) {
      inUse++; // a meeting starts and takes a room
      most = Math.max(most, inUse);
      i++;
    } else {
      inUse--; // a meeting ends first and frees its room
      j++;
    }
  }
  return most;
}

