#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

using Interval = std::pair<int, int>;

int minMeetingRooms(const std::vector<Interval>& intervals) {
    std::vector<int> starts;
    std::vector<int> ends;
    for (const Interval& interval : intervals) {
        starts.push_back(interval.first);
        ends.push_back(interval.second);
    }
    std::sort(starts.begin(), starts.end());
    std::sort(ends.begin(), ends.end());

    int inUse = 0;
    int most = 0;
    std::size_t i = 0;
    std::size_t j = 0;
    while (i < starts.size()) {
        if (starts[i] < ends[j]) {
            inUse++;  // a meeting starts and takes a room
            most = std::max(most, inUse);
            i++;
        } else {
            inUse--;  // a meeting ends first and frees its room
            j++;
        }
    }
    return most;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<Interval> intervals(n);
    for (int i = 0; i < n; i++) {
        std::cin >> intervals[i].first >> intervals[i].second;
    }
    std::cout << minMeetingRooms(intervals) << "\n";
    return 0;
}

