package main

import (
	"fmt"
	"sort"
)

func minMeetingRooms(intervals [][2]int) int {
	starts := make([]int, len(intervals))
	ends := make([]int, len(intervals))
	for k, interval := range intervals {
		starts[k] = interval[0]
		ends[k] = interval[1]
	}
	sort.Ints(starts)
	sort.Ints(ends)

	inUse, most := 0, 0
	i, j := 0, 0
	for i < len(starts) {
		if starts[i] < ends[j] {
			inUse++ // a meeting starts and takes a room
			if inUse > most {
				most = inUse
			}
			i++
		} else {
			inUse-- // a meeting ends first and frees its room
			j++
		}
	}
	return most
}

func main() {
	var n int
	fmt.Scan(&n)
	intervals := make([][2]int, n)
	for i := range intervals {
		fmt.Scan(&intervals[i][0], &intervals[i][1])
	}
	fmt.Println(minMeetingRooms(intervals))
}

